import{_ as d,a0 as l,w as p,s as a,ao as u,I as s,x as e,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"如何使用 FreeDOS Edit | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 FreeDOS Edit | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 FreeDOS Edit | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 FreeDOS Edit | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20210611 How to use the FreeDOS text editor","title":"如何使用 FreeDOS Edit","tag":"202207","desc":""},"relativePath":"202207/20210611 How to use the FreeDOS text editor.md","filePath":"[post].md"}'),n={name:"202207/20210611 How to use the FreeDOS text editor.md"};function m(c,t,f,S,C,b){const r=l("Link");return p(),a("div",null,[t[15]||(t[15]=u('<h1 id="如何使用-freedos-edit" tabindex="-1">如何使用 FreeDOS Edit <a class="header-anchor" href="#如何使用-freedos-edit" aria-label="Permalink to “如何使用 FreeDOS Edit”">​</a></h1><blockquote><p>FreeDOS 提供了一個叫做 FreeDOS Edit 的用户友好的文本編輯器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202207/20/173027t6ctk5cwf9u988p9.jpg" alt=""></p><p>在任何操作系統中，編輯文件都是一項常有的任務。當你想去做一個某事的筆記、寫封信給朋友或升級一個系統配置 —— 你需要一個文本編輯器。FreeDOS 提供了一個用户友好的文本編輯器（也許沒啥想像力）叫做 “FreeDOS Edit”。</p><h3 id="編輯文件" tabindex="-1">編輯文件 <a class="header-anchor" href="#編輯文件" aria-label="Permalink to “編輯文件”">​</a></h3><p>最簡單的啓用 FreeDOS Edit 的方式就就是輸入 <code>EDIT</code>。它提供一個空的編輯器窗口。圖案背景顯示為一個空的“桌面”——提醒你沒有編輯任何文件。</p><p><img src="https://opensource.com/sites/default/files/uploads/edit.png" alt="FreeDOS Edit：未加載任何文件" title="FreeDOS Edit without any files loaded"></p><p>就像多數 DOS 應用程序一樣，你可以按下你鍵盤上的 <code>Alt</code> 鍵來訪問 Edit 的菜單。這就激活了這個菜單。在你按下 <code>Alt</code> 後，Edit 將切換到“菜單”訪問方式，並高亮 “<ruby>文件<rt>File</rt></ruby>” 菜單。如果你想要訪問菜單欄上的一個不同的菜單，可以使用左右方向鍵。按向下的方向鍵並按下回車鍵來“進入”菜單。</p><p><img src="https://opensource.com/sites/default/files/uploads/edit-menu.png" alt="高亮菜單" title="Highlighting the menu"></p><p>你注意到所有菜單標題的第一個字母是不同的顏色麼？這種高亮字母顯示了一種快捷方式。例如，“<ruby>文件<rt>File</rt></ruby>”菜單的“F”高亮為紅色。所以你可以按下 <code>Alt+F</code>（<code>Alt</code> 和 <code>F</code> 同時按下），Edit 會顯示“<ruby>文件<rt>File</rt></ruby>”菜單。</p><p><img src="https://opensource.com/sites/default/files/uploads/edit-file.png" alt="文件菜單" title="The File menu"></p><p>你可以使用“<ruby>文件<rt>File</rt></ruby>”菜單來開始一個新的（空）文件，或打開一個存在的文件。讓我們開始一個新文件，使用方向鍵移動到“<ruby>新建<rt>New</rt></ruby>“然後按下回車鍵。你也可以用 <code>Ctrl+N</code> （<code>Ctrl</code> 和 <code>N</code> 同時按下）打開一個新文件。</p><p><img src="https://opensource.com/sites/default/files/uploads/edit-new.png" alt="編輯一個新的文件" title="Editing a new file"></p><p>此後，編輯文件應該非常簡單。大多數熟悉的快捷鍵都可以在 FreeDOS Edit 中使用：<code>Ctrl+C</code> 複製文本，<code>Ctrl+X</code> 剪貼文本，和 <code>Ctrl+V</code> 將複製的或剪貼的文本粘貼到新的地方。如果你需要在一個長文檔中尋找一個特殊文本，按下 <code>Ctrl+F</code>。保存你的工作成果，請使用 <code>Ctrl+S</code> 以將變更提交到硬盤。</p><h3 id="在-edit-中編程" tabindex="-1">在 Edit 中編程 <a class="header-anchor" href="#在-edit-中編程" aria-label="Permalink to “在 Edit 中編程”">​</a></h3><p>如果你是個程序員，你也許會發現擴展的 ASCII 表是一個有用的工具。DOS 系統支持“拓展的” ASCII字符集，通常被稱之為“代碼頁 437”。0 到 127 的標準字符包括字母 A 到 Z（大寫和小寫）、數字和特殊字符，如標點符號。但是，從 128 到 255 的 DOS 拓展字符包括其它語言字符和“畫線”元素。DOS 程序員有時需要使用這些拓展 ASCII 字符，所以 FreeDOS Edit 可以很容易地查看所有 ASCII 碼和它們的相關字符的表格。</p><p>要查看這個 ASCII 表，請使用“<ruby>工具<rt>Utilities</rt></ruby>”菜單，選擇“<ruby>ASCII 表<rt>ASCII Table</rt></ruby>”菜單項，這將顯示一個包含該表格的窗口。</p><p><img src="https://opensource.com/sites/default/files/uploads/utilities-ascii.png" alt="在工具菜單找到 ASCII 表" title="Find the ASCII Table in the Utilities menu"></p><p>沿着左邊，這張表顯示十六進制值“00”到“F0”，頂部展示了單一值“0”到“F”。這些為每個字符的十六進制代碼提供了一個快速參考。例如，第一行（00）和第一列（0）中的項目具有十六進制值 00 + 0，即0x00（“NULL”值）。而第五行（40）和第二列（1）中的字符，其數值為 40 + 1，即 0x41（字母 “A”）。</p><p><img src="https://opensource.com/sites/default/files/uploads/ascii-table-0x00.png" alt="ASCII 表提供一個便於參考的擴展字符表" title="The ASCII Table provides a handy reference for extended characters"></p><p>當你在表格內移動光標高亮不同的字符時，你會看到表格底部的值發生變化，展示了字符的十進制、十六進制和八進制編碼。例如，移動光標以高亮在 C0 行和第 5 列的“行交叉”字符，顯示這個擴展字符的代碼為 197（十進制）、0xc5（十六進制）和 305（八進制）。在一個程序中，你可以通過輸入十六進制值 0xc5 或八進制“轉義代碼” \\305 來引用這個擴展字符。</p><p><img src="https://opensource.com/sites/default/files/uploads/ascii-0xc5.png" alt="“行交叉”字符是 197（十進制）、0xc5（十六進制）和 305（八進制）"></p><p>請隨意瀏覽 Edit 中的菜單，以發現其他不錯的功能。例如，“<ruby>選項<rt>Options</rt></ruby>”菜單允許你更改 Edit 的行為和外觀。如果你喜歡使用更密集的顯示，可以使用“<ruby>顯示<rt>Display</rt></ruby>”菜單（在“<ruby>選項<rt>Options</rt></ruby>”下）將 Edit 設置為 25、43 或 50 行。你還可以強制 Edit 以單色（黑底白字）或反轉模式（白底黑字）顯示。</p><p>（文內圖片來自 Jim Hall，CC-BY SA 4.0）</p><hr>',25)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),i(r,{href:"https://opensource.com/article/21/6/freedos-text-editor"},{default:o(()=>[...t[0]||(t[0]=[e("https://opensource.com/article/21/6/freedos-text-editor",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("作者：",-1)),i(r,{href:"https://opensource.com/users/jim-hall"},{default:o(()=>[...t[2]||(t[2]=[e("Jim Hall",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),i(r,{href:"https://github.com/yjacks"},{default:o(()=>[...t[4]||(t[4]=[e("yjacks",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const x=d(n,[["render",m]]);export{F as __pageData,x as default};
